        calls++;
        if (calls == 1) return zeroByteAbort(source);
        return FakeStreamFunction([
          textTurn('recovered'),
        ]).call(model, context, cancelToken: cancelToken);
      });

      final events = await wrapped(
        testModel,
        const Context(messages: []),
        cancelToken: source.token,
      ).toList();

