        name: json['name'] as String? ?? '',
        description: json['description'] as String? ?? '',
        schemaJson: json['schemaJson'] as String? ?? '',
        schemaChars: json['schemaChars'] as int? ?? 0,
        schemaTruncated: json['schemaTruncated'] as bool? ?? false,
      );
}
