Future<void> main() async {
  final lengths = <int>[];
  String? firstPrompt;
  for (var i = 0; i < 8; i++) {
    final turns = [
      toolTurn([
        ToolCall(id: 'c1', name: 'bash', arguments: {'command': 'cat big.log'}),
      ]),
      textTurn('done'),
