      if (memorySection.isNotEmpty) memorySection,
      if (messagingSection.isNotEmpty) messagingSection,
      if (mcpSection.isNotEmpty) mcpSection,
      if (extSection.isNotEmpty) extSection,
    ].join('\n\n');
