import json, re
# The matcher prints each JSONL line as a Dart-escaped single-quoted literal.
# Un-escape: the JSONL content itself is one line; escapes seen: \\n, \\', \\\\, \\t
def unescape(s):
    out=[]; i=0
    while i < len(s):
        c=s[i]
        if c=='\\' and i+1<len(s):
            n=s[i+1]
            mapping={'n':'\n','t':'\t','r':'\r',"'":"'",'"':'"','\\':'\\','$':'$'}
            if n in mapping: out.append(mapping[n]); i+=2; continue
        out.append(c); i+=1
    return ''.join(out)

def records(path):
    txt=open(path).read()
    recs=[]
    for l in txt.splitlines():
        s=l.strip()
        if s.startswith("'{\"type\":"):
            if s.endswith("'"): s=s[1:-1]
            recs.append(unescape(s))
    return recs

E = records('/tmp/exp_block.txt')
A = records('/tmp/act_block.txt')
print('exp records:', len(E), 'act records:', len(A))
# match records by type+messageCount
def key(r):
    m=re.search(r'"customType":"([a-z_]+)"', r)
    t=m.group(1) if m else 'other'
    mc=re.search(r'"messageCount":(\d+)', r)
    return (t, mc.group(1) if mc else '')
for er in E:
    k=key(er)
    match=[ar for ar in A if key(ar)==k]
    if k[0]=='trajectory_prompt_blob':
        pe=json.loads(er)['data']['text']; pa=json.loads(match[0])['data']['text']
        print('PROMPT normalized lens: exp', len(pe), 'act', len(pa), 'identical:', pe==pa)
    elif k[0]=='model_request_summary':
        print(k, 'identical:', er==match[0], 'len', len(er))
EOF"}

